const steps = [
  'scaffold-pinned',
  'read-tools',
  'resource-prompt',
  'inspector-verify-reads',
  'gated-refund',
  'inspector-verify-money',
];
const rules = { 'gated-refund': ['read-tools', 'inspector-verify-reads'] };
function orderOK(order) {
  const pos = {};
  order.forEach((s, i) => (pos[s] = i));
  for (const [step, deps] of Object.entries(rules))
    for (const d of deps) if (pos[d] > pos[step]) return 'violated: ' + step + ' before ' + d;
  return 'order sound';
}
console.log(orderOK(steps));
console.log(orderOK(['gated-refund', 'scaffold-pinned', 'read-tools', 'resource-prompt', 'inspector-verify-reads', 'inspector-verify-money']));

